-- IDM 6.43's own list of file types it takes over (read from Options > File types). Replaces the
-- original seed only when the user never changed it. A trailing * is a prefix match (R0* = r00, r01...).
UPDATE settings SET value = '["3gp","7z","aac","ace","aif","apk","arj","asf","avi","bin","bz2","exe","gz","gzip","img","iso","lzh","m4a","m4v","mkv","mov","mp3","mp4","mpa","mpe","mpeg","mpg","msi","msu","ogg","ogv","pdf","plj","pps","ppt","qt","r0*","r1*","ra","rar","rm","rmvb","sea","sit","sitx","tar","tif","tiff","wav","wma","wmv","z","zip"]'
WHERE key = 'capture_extensions' AND value = '["3g2","3gp","7z","aac","aif","aiff","ape","apk","appimage","arj","avi","bin","bz2","cab","cbr","cbz","deb","dmg","doc","docx","exe","flac","flv","gz","gzip","iso","jar","m4a","m4v","mkv","mov","mp3","mp4","mpeg","mpg","msi","msix","msu","ogg","opus","pdf","pkg","ppt","pptx","rar","rpm","rtf","tar","tbz2","tgz","torrent","ts","txz","wav","webm","wim","wma","wmv","xls","xlsx","xz","zip","zipx"]';
